import os,subprocess as s,sys
def fail(m):
    print(m);sys.exit(1)
def run(env):
    E={k:v for k,v in os.environ.items() if k not in ('TMUX','TMUX_PANE','WEZTERM_PANE','WT_SESSION','TERM_PROGRAM')};E.update(env)
    p=s.run([sys.executable,'_tools/kbmon.py','--split','--dry-run'],capture_output=True,text=True,env=E,timeout=60)
    return p.returncode,p.stdout
rc,o=run({'WEZTERM_PANE':'7'})
if rc!=0 or 'wezterm' not in o or 'split-pane' not in o or 'kbmon.py' not in o or '--interval 60' not in o: fail('wezterm: %s %r'%(rc,o))
